require __DIR__.'/ui.php';role(['admin','gerente','vendedor']);$p=db();
if(isset($_GET['convert'])){$id=(int)$_GET['convert'];$s=$p->prepare("SELECT * FROM online_orders WHERE id=?");$s->execute([$id]);$o=$s->fetch();if($o&&!$o['converted_order_id']){$p->beginTransaction();try{$num=next_number('PED-','orders');$p->prepare("INSERT INTO orders(number,occasion,payment_method,subtotal,delivery_fee,total,cost,profit,status,production_stage,art_status,delivery_type,delivery_date,delivery_time,recipient_name,recipient_phone,delivery_address,notes)VALUES(?,?,?,?,?,?,?,?,?,'Novo','Não se aplica',?,?,?,?,?,?,?)")->execute([$num,$o['occasion'],$o['payment_method'],$o['subtotal'],$o['delivery_fee'],$o['total'],0,$o['total'],'Recebido',$o['delivery_type'],$o['delivery_date'],$o['delivery_time'],$o['recipient_name'],$o['recipient_phone'],$o['address'],$o['notes']]);$oid=(int)$p->lastInsertId();$it=$p->prepare("SELECT * FROM online_order_items WHERE online_order_id=?");$it->execute([$id]);foreach($it as $i){$ps=$p->prepare("SELECT * FROM products WHERE id=?");$ps->execute([$i['product_id']]);$pr=$ps->fetch();$cost=$pr['cost']??0;$p->prepare("INSERT INTO order_items(order_id,product_id,product_name,qty,unit_price,unit_cost)VALUES(?,?,?,?,?,?)")->execute([$oid,$i['product_id'],$i['product_name'],$i['qty'],$i['unit_price'],$cost]);$avail=available_stock_for_product((int)$i['product_id'],(float)$i['qty']);if(!$avail['ok'])throw new RuntimeException($avail['message']);consume_product_stock((int)$i['product_id'],(float)$i['qty'],'order',$oid);}if($o['delivery_type']==='Entrega local')$p->prepare("INSERT INTO deliveries(order_id,status)VALUES(?,'Pendente')")->execute([$oid]);timeline_event($oid,'online_conversion','Pedido online convertido','Origem: '.$o['public_number']);$p->prepare("UPDATE online_orders SET status='Convertido',converted_order_id=? WHERE id=?")->execute([$oid,$id]);$p->commit();flash('success','Pedido online convertido em '.$num);}catch(Throwable $e){$p->rollBack();flash('error',$e->getMessage());}}go('online-orders.php');}
$rows=$p->query("SELECT * FROM online_orders ORDER BY id DESC")->fetchAll();page_head('Pedidos online');?>
<div class="card"><div class="actions"><a class="btn primary" target="_blank" href="catalog.php">Abrir catálogo público</a></div><div class="table"><table><tr><th>Pedido</th><th>Cliente</th><th>WhatsApp</th><th>Total</th><th>Entrega</th><th>Status</th><th></th></tr><?php foreach($rows as $o):?><tr><td><?=e($o['public_number'])?></td><td><?=e($o['customer_name'])?></td><td><?=e($o['whatsapp'])?></td><td><?=money($o['total'])?></td><td><?=e($o['delivery_date'])?> <?=e($o['neighborhood'])?></td><td><?=e($o['status'])?></td><td><?php if(!$o['converted_order_id']):?><a class="btn green" href="?convert=<?=$o['id']?>">Converter em pedido</a><?php else:?>Pedido #<?=$o['converted_order_id']?><?php endif;?></td></tr><?php endforeach;?></table></div></div><?php page_foot();?>